solution.code:
#include <stdio.h>

int main() {
    int a[] = {2, 4, 6, 8, 10};
    int prefix[6] = {0};
    for (int i = 0; i < 5; i++) {
        prefix[i + 1] = prefix[i] + a[i];
    }
    int left = 1, right = 3;
    printf("%d\n", prefix[right + 1] - prefix[left]);
    return 0;
}
